cat > $D/uringwait.c <<'EOF'
#define _GNU_SOURCE
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/syscall.h>
int main(void) {
    unsigned int p[30];
    memset(p, 0, sizeof p);
    long fd = syscall(425 /*io_uring_setup*/, 8, p);
    if (fd < 0) { perror("io_uring_setup"); return 1; }
    printf("ring fd=%ld pid=%d tid=%ld -- parking in io_uring_enter GETEVENTS min_complete=1\n",
           fd, getpid(), syscall(SYS_gettid));
    fflush(stdout);
    /* no SQEs submitted; this completion never arrives -> blocks forever */
    long r = syscall(426 /*io_uring_enter*/, fd, 0, 1, 1 /*IORING_ENTER_GETEVENTS*/, NULL, 0);
    printf("returned %ld\n", r);
    return 0;
}
EOF
gcc -O0 -o $D/uringwait $D/uringwait.c && echo "build: ok"

